import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validateInput: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validateInput = compileSchema(resolved.name, resolved.inputSchema);
    if (typeof definition === 'function') {
      this.dynamicValidators.set(resolved.inputSchema, validateInput);
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validateInput});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against inputSchema; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = resolveValidator(name, tool, this.dynamicValidators);
    const rejection = validateToolInput(name, input, validate);
    if (rejection) return rejection;
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

function resolveValidator(
  name: string,
  tool: StoredTool,
  cache: WeakMap<object, ValidateFunction>
): ValidateFunction {
  if (typeof tool.definitionSource !== 'function') return tool.validateInput;
  const current = tool.definitionSource();
  const cached = cache.get(current.inputSchema);
  if (cached) return cached;
  const compiled = compileSchema(name, current.inputSchema);
  cache.set(current.inputSchema, compiled);
  return compiled;
}

const ajv = new Ajv({allErrors: true, format: false});

function compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${detail}`, {cause: error});
  }
}

function validateToolInput(
  name: string,
  input: Record<string, unknown>,
  validate: ValidateFunction
): ToolResponse | null {
  const accepted = validate(input);
  if (accepted === true) return null;
  const rawIssues = validate.errors ?? [];
  const issues = rawIssues.map(issue => summarizeIssue(issue));
  log.warn('tool', 'input validation failed', {name, issues});
  const descriptions = rawIssues.map(issue => describeIssue(issue));
  const detail = descriptions.length > 0 ? descriptions.join('; ') : 'input did not match schema';
  return {result: `Invalid input for tool "${name}": ${detail}`};
}

interface ValidationIssue {
  keyword: string;
  dataPath?: string;
  instancePath?: string;
  params: object;
}

interface IssueSummary {
  path: string;
  keyword: string;
}

function summarizeIssue(issue: ValidationIssue): IssueSummary {
  return {path: resolveIssuePath(issue), keyword: issue.keyword};
}

function describeIssue(issue: ValidationIssue): string {
  const path = resolveIssuePath(issue);
  if (issue.keyword === 'required') {
    return `missing required property "${path}"`;
  }
  if (issue.keyword === 'type' && 'type' in issue.params) {
    return `property "${path}" must be of type ${String(issue.params.type)}`;
  }
  return `property "${path}" failed "${issue.keyword}" validation`;
}

function resolveIssuePath(issue: ValidationIssue): string {
  const basePath = normalizeSchemaPath(issue.instancePath ?? issue.dataPath ?? '');
  if (issue.keyword === 'required' && 'missingProperty' in issue.params) {
    const propertyName = String(issue.params.missingProperty);
    return basePath ? `${basePath}.${propertyName}` : propertyName;
  }
  return basePath || '<root>';
}

function normalizeSchemaPath(rawPath: string): string {
  const trimmed = rawPath.replace(/^[./]+/, '');
  return trimmed.replace(/\//g, '.');
